// 解析 Claude 回傳的結構化文案
const response = $input.first().json;
const raw = response.content[0].text;

function extract(label) {
  const regex = new RegExp(`【${label}】[^：：]*[：:]([\\s\\S]*?)(?=【|$)`, 'i');
  const match = raw.match(regex);
  return match ? match[1].trim() : '';
}

const title = extract('貼文標題');
const hook = extract('第一句Hook');
const short_copy = extract('短版文案');
const full_copy = extract('完整版文案');
const card_line1 = extract('圖卡文案第一行');
const card_line2 = extract('圖卡文案第二行');
const card_line3 = extract('圖卡文案第三行');
const cta = extract('CTA');
const hashtags = extract('Hashtag');
const disclaimer = extract('免責聲明');
const image_concept = extract('圖片主視覺概念');
const dalle_prompt = extract('DALLE Prompt 1:1');
const risk_level = extract('合規風險等級');
const audit_result = extract('審查結果');

// 組裝 LINE 發布格式
const line_message = `${title}\n\n${full_copy}\n\n${cta}\n\n${hashtags}\n\n${disclaimer}`;

return [{
  json: {
    title,
    hook,
    short_copy,
    full_copy,
    card_line1,
    card_line2,
    card_line3,
    cta,
    hashtags,
    disclaimer,
    image_concept,
    dalle_prompt,
    risk_level,
    audit_result,
    line_message,
    raw_response: raw,
    created_at: new Date().toISOString()
  }
}];

